// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address owner, uint256 tokenId) public {
        vm.assume(owner != address(0));

        if (c.uniqueTokensOutstanding() == 0) {
            c.createGameItem("name", "uri", false, true, 0, 0, 1);
        }

        uint256 count = c.uniqueTokensOutstanding();
        uint256 id = tokenId % count;

        NeuronMock nrn = new NeuronMock();
        GameItems local = new GameItems(address(this), address(this));
        local.createGameItem("name", "uri", false, true, 100, 1, 10);
        local.instantiateNeuronContract(address(nrn));
        nrn.setBalance(owner, 5);
        nrn.setAllowance(owner, address(local), 5);

        vm.prank(owner);
        local.mint(id, 1);

        uint256 returned = local.balanceOf(owner, id);

        assertTrue(returned == 1);
    }
}

contract NeuronMock {
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowed;

    function setBalance(address who, uint256 amt) public {
        balances[who] = amt;
    }
    function setAllowance(address owner, address spender, uint256 amt) public {
        allowed[owner][spender] = amt;
    }

    function balanceOf(address account) external view returns (uint256) {
        return balances[account];
    }

    function approveSpender(address account, uint256 amount) external {
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (allowed[from][msg.sender] < amount) return false;
        if (balances[from] < amount) return false;
        balances[from] -= amount;
        balances[to] += amount;
        allowed[from][msg.sender] -= amount;
        return true;
    }

    function allowance(address owner, address spender) external view returns (uint256) {
        return allowed[owner][spender];
    }
}
